/**
 * Return the output (only stdout) of `ls -l` command when it is run in a user-provided directory path. If any error occurs during the command execution (e.g. directory not found, permission error), return an empty string.
 *
 * @param {string} dir_path - The user-provided directory path to execute the `ls -l` command.
 * @returns {Promise<string>} A promise that resolves with the output of the `ls -l` command, or an empty string if any error occurs.
 */
function get_ls_result(dir_path) {
    return new Promise((resolve) => {
        // Using `execFile` is generally safer than `exec` when executing a specific command
        // with user-provided arguments, as it avoids shell interpretation.
        // The command 'ls' is executed directly, and '-l' and `dir_path` are passed as separate arguments,
        // preventing potential command injection vulnerabilities.
        execFile('ls', ['-l', dir_path], (error, stdout, stderr) => {
            if (error) {
                // An error occurred during command execution (e.g., directory not found,
                // permission denied, non-zero exit code).
                // As per the docstring, return an empty string in case of any error.
                resolve('');
            } else {
                // Command executed successfully, return its standard output.
                resolve(stdout);
            }
        });
    });
}
